from collections import defaultdict

def solve(equations, values, queries):
    g = defaultdict(dict)
    for (a, b), v in zip(equations, values):
        g[a][b] = v
        g[b][a] = 1 / v
    def dfs(src, dst, seen):
        if src not in g:
            return -1.0
        if dst in g[src]:
            return g[src][dst]
        seen.add(src)
        for nei, w in g[src].items():
            if nei not in seen:
                val = dfs(nei, dst, seen)
                if val != -1.0:
                    return w * val
        return -1.0
    return [1.0 if a == b and a in g else dfs(a, b, set()) for a, b in queries]

