def solve(nums):
    nums = [1] + nums + [1]
    n = len(nums)
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n):
        for left in range(n - length):
            right = left + length
            for k in range(left + 1, right):
                dp[left][right] = max(dp[left][right], dp[left][k] + dp[k][right] + nums[left] * nums[k] * nums[right])
    return dp[0][-1]

def solve(dungeon):
    m, n = len(dungeon), len(dungeon[0])
    dp = [[float('inf')] * (n + 1) for _ in range(m + 1)]
    dp[m][n - 1] = dp[m - 1][n] = 1
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            need = min(dp[i + 1][j], dp[i][j + 1]) - dungeon[i][j]
            dp[i][j] = max(1, need)
    return dp[0][0]

from collections import defaultdict, deque

def solve(words):
    graph = defaultdict(set)
    indeg = {c: 0 for w in words for c in w}
    for a, b in zip(words, words[1:]):
        if len(a) > len(b) and a.startswith(b):
            return ''
        for x, y in zip(a, b):
            if x != y:
                if y not in graph[x]:
                    graph[x].add(y)
                    indeg[y] += 1
                break
    q = deque([c for c in indeg if indeg[c] == 0])
    ans = []
    while q:
        c = q.popleft()
        ans.append(c)
        for nei in graph[c]:
            indeg[nei] -= 1
            if indeg[nei] == 0:
                q.append(nei)
    return ''.join(ans) if len(ans) == len(indeg) else ''

import heapq

def solve(times, n, k):
    graph = [[] for _ in range(n + 1)]
    for u, v, w in times:
        graph[u].append((v, w))
    pq = [(0, k)]
    dist = {}
    while pq:
        d, u = heapq.heappop(pq)
        if u in dist:
            continue
        dist[u] = d
        for v, w in graph[u]:
            if v not in dist:
                heapq.heappush(pq, (d + w, v))
    return max(dist.values()) if len(dist) == n else -1

def solve(n, flights, src, dst, k):
    dist = [float('inf')] * n
    dist[src] = 0
    for _ in range(k + 1):
        temp = dist[:]
        for u, v, w in flights:
            if dist[u] != float('inf'):
                temp[v] = min(temp[v], dist[u] + w)
        dist = temp
    return -1 if dist[dst] == float('inf') else dist[dst]

from functools import lru_cache

def solve(s1, s2):
    @lru_cache(None)
    def dfs(a, b):
        if a == b:
            return True
        if sorted(a) != sorted(b):
            return False
        n = len(a)
        for i in range(1, n):
            if dfs(a[:i], b[:i]) and dfs(a[i:], b[i:]):
                return True
            if dfs(a[:i], b[n-i:]) and dfs(a[i:], b[:n-i]):
                return True
        return False
    return dfs(s1, s2)

from collections import deque

def solve(s):
    def valid(x):
        bal = 0
        for c in x:
            if c == '(':
                bal += 1
            elif c == ')':
                bal -= 1
                if bal < 0:
                    return False
        return bal == 0
    q = deque([s])
    seen = {s}
    ans = []
    found = False
    while q:
        cur = q.popleft()
        if valid(cur):
            ans.append(cur)
            found = True
        if found:
            continue
        for i, c in enumerate(cur):
            if c not in '()':
                continue
            nxt = cur[:i] + cur[i+1:]
            if nxt not in seen:
                seen.add(nxt)
                q.append(nxt)
    return ans

