def solve(board):
    start = ''.join(str(x) for row in board for x in row)
    target = '123450'
    neigh = {0:[1,3],1:[0,2,4],2:[1,5],3:[0,4],4:[1,3,5],5:[2,4]}
    q = deque([(start,0)])
    seen = {start}
    while q:
        state,d = q.popleft()
        if state == target:
            return d
        z = state.index('0')
        for n in neigh[z]:
            arr = list(state)
            arr[z], arr[n] = arr[n], arr[z]
            nxt = ''.join(arr)
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt,d+1))
    return -1

