def solve(target):
    dp = [0] * (target + 1)
    for t in range(1, target + 1):
        k = t.bit_length()
        if t == (1 << k) - 1:
            dp[t] = k
            continue
        dp[t] = k + 1 + dp[(1 << k) - 1 - t]
        for m in range(k - 1):
            dist = (1 << (k - 1)) - (1 << m)
            dp[t] = min(dp[t], k - 1 + 1 + m + 1 + dp[t - dist])
    return dp[target]

def solve(s):
    n = len(s)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            dp[i][j] = dp[i + 1][j] + 1
            for k in range(i + 1, j + 1):
                if s[k] == s[i]:
                    dp[i][j] = min(dp[i][j], dp[i + 1][k - 1] + dp[k][j])
    return dp[0][-1]

def solve(nums, k):
    s = sum(nums)
    if s % k:
        return False
    target = s // k
    nums.sort(reverse=True)
    buckets = [0] * k
    def dfs(i):
        if i == len(nums):
            return True
        for j in range(k):
            if buckets[j] + nums[i] <= target:
                buckets[j] += nums[i]
                if dfs(i + 1):
                    return True
                buckets[j] -= nums[i]
            if buckets[j] == 0:
                break
        return False
    return dfs(0)

from collections import deque

def solve(grid):
    m, n = len(grid), len(grid[0])
    q = deque()
    found = False
    def dfs(r, c):
        if r < 0 or c < 0 or r >= m or c >= n or grid[r][c] != 1:
            return
        grid[r][c] = 2
        q.append((r, c))
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            dfs(r + dr, c + dc)
    for i in range(m):
        if found:
            break
        for j in range(n):
            if grid[i][j] == 1:
                dfs(i, j)
                found = True
                break
    steps = 0
    while q:
        for _ in range(len(q)):
            r, c = q.popleft()
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    if grid[nr][nc] == 1:
                        return steps
                    if grid[nr][nc] == 0:
                        grid[nr][nc] = 2
                        q.append((nr, nc))
        steps += 1

def solve(nums):
    if not nums:
        return 0
    up = down = 1
    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            up = down + 1
        elif nums[i] < nums[i - 1]:
            down = up + 1
    return max(up, down)

def solve(grid):
    n = len(grid)
    dp = {(0, 0): grid[0][0]}
    for k in range(1, 2 * n - 1):
        ndp = {}
        for i1 in range(max(0, k - n + 1), min(n, k + 1)):
            for i2 in range(max(0, k - n + 1), min(n, k + 1)):
                j1, j2 = k - i1, k - i2
                if j1 >= n or j2 >= n or grid[i1][j1] == -1 or grid[i2][j2] == -1:
                    continue
                best = -1
                for a in (i1, i1 - 1):
                    for b in (i2, i2 - 1):
                        if (a, b) in dp:
                            best = max(best, dp[(a, b)])
                if best < 0:
                    continue
                val = best + grid[i1][j1]
                if i1 != i2:
                    val += grid[i2][j2]
                ndp[(i1, i2)] = val
        dp = ndp
    return max(0, dp.get((n - 1, n - 1), -1))

