from collections import Counter

def solve(stickers, target):
    counts = [Counter(s) for s in stickers]
    @lru_cache(None)
    def dfs(rem):
        if not rem:
            return 0
        need = Counter(rem)
        ans = float('inf')
        for c in counts:
            if rem[0] not in c:
                continue
            nxt = ''.join(ch * max(0, need[ch] - c[ch]) for ch in sorted(need))
            sub = dfs(nxt)
            if sub != -1:
                ans = min(ans, 1 + sub)
        return -1 if ans == float('inf') else ans
    return dfs(''.join(sorted(target)))

