from functools import lru_cache

def solve(ring, key):
    pos = defaultdict(list)
    for i, c in enumerate(ring):
        pos[c].append(i)
    n = len(ring)
    @lru_cache(None)
    def dfs(i, p):
        if i == len(key):
            return 0
        ans = float('inf')
        for j in pos[key[i]]:
            d = abs(j - p)
            d = min(d, n - d)
            ans = min(ans, d + 1 + dfs(i + 1, j))
        return ans
    return dfs(0, 0)

def solve(stones, k):
    n = len(stones)
    if (n - 1) % (k - 1):
        return -1
    pre = [0]
    for x in stones:
        pre.append(pre[-1] + x)
    dp = [[0] * n for _ in range(n)]
    for m in range(k, n + 1):
        for i in range(n - m + 1):
            j = i + m - 1
            dp[i][j] = min(dp[i][t] + dp[t + 1][j] for t in range(i, j, k - 1))
            if (m - 1) % (k - 1) == 0:
                dp[i][j] += pre[j + 1] - pre[i]
    return dp[0][-1]

def solve(words, target):
    MOD = 10 ** 9 + 7
    m = len(words[0])
    cnt = [[0] * 26 for _ in range(m)]
    for w in words:
        for i, c in enumerate(w):
            cnt[i][ord(c) - 97] += 1
    dp = [0] * (len(target) + 1)
    dp[0] = 1
    for i in range(m):
        for j in range(len(target) - 1, -1, -1):
            c = ord(target[j]) - 97
            dp[j + 1] = (dp[j + 1] + dp[j] * cnt[i][c]) % MOD
    return dp[-1]

def solve(n, connections):
    g = [[] for _ in range(n)]
    for u, v in connections:
        g[u].append(v)
        g[v].append(u)
    low = [0] * n
    disc = [-1] * n
    ans = []
    t = 0
    def dfs(u, p):
        nonlocal t
        disc[u] = low[u] = t
        t += 1
        for v in g[u]:
            if v == p:
                continue
            if disc[v] == -1:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    ans.append([u, v])
            else:
                low[u] = min(low[u], disc[v])
    dfs(0, -1)
    return ans

from collections import defaultdict, deque

def solve(routes, source, target):
    if source == target:
        return 0
    stop_to_bus = defaultdict(list)
    for i, r in enumerate(routes):
        for s in r:
            stop_to_bus[s].append(i)
    q = deque([(source, 0)])
    seen_stop = {source}
    seen_bus = set()
    while q:
        stop, d = q.popleft()
        for b in stop_to_bus[stop]:
            if b in seen_bus:
                continue
            seen_bus.add(b)
            for nxt in routes[b]:
                if nxt == target:
                    return d + 1
                if nxt not in seen_stop:
                    seen_stop.add(nxt)
                    q.append((nxt, d + 1))
    return -1

