            if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in seen:
                seen.add((nr, nc))
                heapq.heappush(pq, (max(t, grid[nr][nc]), nr, nc))

from collections import deque

def solve(graph):
    n = len(graph)
    q = deque((i, 1 << i, 0) for i in range(n))
    seen = {(i, 1 << i) for i in range(n)}
    target = (1 << n) - 1
    while q:
        u, mask, d = q.popleft()
        if mask == target:
            return d
        for v in graph[u]:
            nm = mask | (1 << v)
            if (v, nm) not in seen:
                seen.add((v, nm))
                q.append((v, nm, d + 1))

def solve(num, target):
    ans = []
    def dfs(i, expr, val, prev):
        if i == len(num):
            if val == target:
                ans.append(expr)
            return
        for j in range(i + 1, len(num) + 1):
            s = num[i:j]
            if len(s) > 1 and s[0] == '0':
                break
            x = int(s)
            if i == 0:
                dfs(j, s, x, x)
            else:
                dfs(j, expr + '+' + s, val + x, x)
                dfs(j, expr + '-' + s, val - x, -x)
                dfs(j, expr + '*' + s, val - prev + prev * x, prev * x)
    dfs(0, '', 0, 0)
    return ans

from collections import Counter

def solve(formula):
    i = 0
    def parse():
        nonlocal i
        cnt = Counter()
        while i < len(formula) and formula[i] != ')':
            if formula[i] == '(':
                i += 1
                sub = parse()
                i += 1
                start = i
                while i < len(formula) and formula[i].isdigit():
                    i += 1
                mult = int(formula[start:i] or '1')
                for k, v in sub.items():
                    cnt[k] += v * mult
            else:
                start = i
                i += 1
                while i < len(formula) and formula[i].islower():
                    i += 1
                atom = formula[start:i]
                start = i
                while i < len(formula) and formula[i].isdigit():
                    i += 1
                cnt[atom] += int(formula[start:i] or '1')
        return cnt
    res = parse()
    return ''.join(k + (str(res[k]) if res[k] > 1 else '') for k in sorted(res))

def solve(s):
    i = 0
    def expr():
        nonlocal i
        stack, num, sign = [], 0, '+'
        while i < len(s):
            c = s[i]
            if c.isdigit():
                num = num * 10 + int(c)
            if c == '(':
                i += 1
                num = expr()
            if (not c.isdigit() and c != ' ') or i == len(s) - 1:
                if sign == '+': stack.append(num)
                elif sign == '-': stack.append(-num)
                elif sign == '*': stack[-1] *= num
                elif sign == '/': stack[-1] = int(stack[-1] / num)
                sign = c
                num = 0
            if c == ')':
                break
            i += 1
        return sum(stack)
    return expr()

def solve(s):
    MOD = 10 ** 9 + 7
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for l in range(2, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            if s[i] == s[j]:
                lo, hi = i + 1, j - 1
                while lo <= hi and s[lo] != s[i]:
                    lo += 1
                while lo <= hi and s[hi] != s[i]:
                    hi -= 1
                if lo > hi:
                    dp[i][j] = dp[i + 1][j - 1] * 2 + 2
                elif lo == hi:
                    dp[i][j] = dp[i + 1][j - 1] * 2 + 1
                else:
                    dp[i][j] = dp[i + 1][j - 1] * 2 - dp[lo + 1][hi - 1]
            else:
                dp[i][j] = dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1]
            dp[i][j] %= MOD
    return dp[0][-1]

from functools import lru_cache

def solve(boxes):
    @lru_cache(None)
    def dfs(l, r, k):
        if l > r:
            return 0
        while l < r and boxes[r] == boxes[r - 1]:
            r -= 1
            k += 1
        ans = dfs(l, r - 1, 0) + (k + 1) ** 2
        for i in range(l, r):
            if boxes[i] == boxes[r]:
                ans = max(ans, dfs(l, i, k + 1) + dfs(i + 1, r - 1, 0))
        return ans
    return dfs(0, len(boxes) - 1, 0)

from collections import defaultdict, deque

def solve(n, edges, t, target):
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    q = deque([(1, 1.0, 0)])
    seen = {1}
    while q:
        node, p, d = q.popleft()
        children = [x for x in g[node] if x not in seen]
        if d == t or not children:
            if node == target and d == t or (node == target and not children and d < t):
                return p
            continue
        prob = p / len(children)
        for c in children:
            seen.add(c)
            q.append((c, prob, d + 1))
    return 0.0

