def solve(equations):
    parent = list(range(26))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(a, b):
        parent[find(a)] = find(b)
    for e in equations:
        if e[1:3] == '==':
            union(ord(e[0]) - 97, ord(e[3]) - 97)
    for e in equations:
        if e[1:3] == '!=' and find(ord(e[0]) - 97) == find(ord(e[3]) - 97):
            return False
    return True

from collections import defaultdict

def solve(words):
    pref = defaultdict(list)
    for w in words:
        for i in range(len(w) + 1):
            pref[w[:i]].append(w)
    ans = []
    def dfs(square):
        if len(square) == len(words[0]):
            ans.append(square[:])
            return
        idx = len(square)
        p = ''.join(w[idx] for w in square)
        for cand in pref[p]:
            square.append(cand)
            dfs(square)
            square.pop()
    for w in words:
        dfs([w])
    return ans

def solve(expression):
    def eval_expr(expr, env):
        if expr[0] != '(':
            if expr[0] == '-' or expr[0].isdigit():
                return int(expr)
            return env[expr]
        expr = expr[1:-1]
        parts = []
        bal = 0
        cur = ''
        for c in expr:
            if c == ' ' and bal == 0:
                if cur:
                    parts.append(cur)
                    cur = ''
            else:
                cur += c
                if c == '(':
                    bal += 1
                elif c == ')':
                    bal -= 1
        if cur:
            parts.append(cur)
        op = parts[0]
        if op == 'add':
            return eval_expr(parts[1], env.copy()) + eval_expr(parts[2], env.copy())
        if op == 'mult':
            return eval_expr(parts[1], env.copy()) * eval_expr(parts[2], env.copy())
        new_env = env.copy()
        i = 1
        while i < len(parts) - 1:
            new_env[parts[i]] = eval_expr(parts[i + 1], new_env)
            i += 2
        return eval_expr(parts[-1], new_env)
    return eval_expr(expression, {})

