def solve(board, hand):
    hand = ''.join(sorted(hand))
    def shrink(s):
        changed = True
        while changed:
            changed = False
            i = 0
            ns = ''
            while i < len(s):
                j = i
                while j < len(s) and s[j] == s[i]:
                    j += 1
                if j - i >= 3:
                    changed = True
                else:
                    ns += s[i:j]
                i = j
            s = ns
        return s
    @lru_cache(None)
    def dfs(b, h):
        b = shrink(b)
        if not b:
            return 0
        if not h:
            return float('inf')
        ans = float('inf')
        for i, c in enumerate(h):
            if i > 0 and h[i] == h[i - 1]:
                continue
            for j in range(len(b) + 1):
                ans = min(ans, 1 + dfs(b[:j] + c + b[j:], h[:i] + h[i + 1:]))
        return ans
    res = dfs(board, hand)
    return -1 if res == float('inf') else res

def solve(s, dictionary):
    words = set(dictionary)
    n = len(s)
    dp = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        dp[i] = dp[i + 1] + 1
        for j in range(i + 1, n + 1):
            if s[i:j] in words:
                dp[i] = min(dp[i], dp[j])
    return dp[0]

from functools import lru_cache

def solve(matrix):
    if not matrix:
        return 0
    m, n = len(matrix), len(matrix[0])
    @lru_cache(None)
    def dfs(r, c):
        ans = 1
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and matrix[nr][nc] > matrix[r][c]:
                ans = max(ans, 1 + dfs(nr, nc))
        return ans
    return max(dfs(i, j) for i in range(m) for j in range(n))

def solve(n, k):
    MOD = 10**9 + 7
    dp = [1] + [0] * k
    for i in range(2, n + 1):
        ndp = [0] * (k + 1)
        s = 0
        for j in range(k + 1):
            s += dp[j]
            if j >= i:
                s -= dp[j - i]
            ndp[j] = s % MOD
        dp = ndp
    return dp[k]

def solve(n, edges, source, destination):
    g = [[] for _ in range(n)]
    for u, v in edges:
        g[u].append(v)
    state = [0] * n
    def dfs(u):
        if state[u]:
            return state[u] == 2
        if not g[u]:
            return u == destination
        state[u] = 1
        for v in g[u]:
            if not dfs(v):
                return False
