def solve(n, edges, prob, start, end):
    g = [[] for _ in range(n)]
    for (u, v), p in zip(edges, prob):
        g[u].append((v, p))
        g[v].append((u, p))
    pq = [(-1.0, start)]
    best = [0.0] * n
    best[start] = 1.0
    while pq:
        p, u = heapq.heappop(pq)
        p = -p
        if u == end:
            return p
        if p < best[u]:
            continue
        for v, w in g[u]:
            np = p * w
            if np > best[v]:
                best[v] = np
                heapq.heappush(pq, (-np, v))
    return 0.0

