from collections import Counter

def solve(tasks, n):
    freq = Counter(tasks)
    mx = max(freq.values())
    cnt = sum(v == mx for v in freq.values())
    return max(len(tasks), (mx - 1) * (n + 1) + cnt)

def solve(s):
    def ok(i, j):
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1
            j -= 1
        return True
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            return ok(i + 1, j) or ok(i, j - 1)
        i += 1
        j -= 1
    return True

