def solve(pattern, s):
    words = s.split()
    if len(pattern) != len(words):
        return False
    a = {}
    b = {}
    for c, w in zip(pattern, words):
        if a.get(c, w) != w or b.get(w, c) != c:
            return False
        a[c] = w
        b[w] = c
    return True

def solve(arr, k):
    n = len(arr)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        mx = 0
        for j in range(1, min(k, i) + 1):
            mx = max(mx, arr[i - j])
            dp[i] = max(dp[i], dp[i - j] + mx * j)
    return dp[n]

from collections import defaultdict, deque

def solve(words, start):
    words = set(words)
    words.add(start)
    pats = defaultdict(list)
    for w in words:
        for i in range(len(w)):
            pats[w[:i] + '*' + w[i+1:]].append(w)
    dist = {start: 0}
    q = deque([start])
    while q:
        w = q.popleft()
        for i in range(len(w)):
            p = w[:i] + '*' + w[i+1:]
            for nw in pats[p]:
                if nw not in dist:
                    dist[nw] = dist[w] + 1
                    q.append(nw)
    return dist

def solve(n):
    dp = [0] * (n + 1)
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + 1
        if i % 2 == 0:
            dp[i] = min(dp[i], dp[i // 2] + 1)
        if i % 3 == 0:
            dp[i] = min(dp[i], dp[i // 3] + 1)
    return dp[n]

from functools import lru_cache

def solve(cost):
    n = len(cost)
    @lru_cache(None)
    def dfs(r, mask):
        if r == n:
            return 0
        ans = float('inf')
        for c in range(n):
            if not (mask >> c) & 1:
                ans = min(ans, cost[r][c] + dfs(r + 1, mask | (1 << c)))
        return ans
    return dfs(0, 0)

def solve(n, edges):
    g = [[] for _ in range(n)]
    for u, v, w in edges:
        g[u].append((v, w))
        g[v].append((u, w))
    ans = 0
    def dfs(u, p):
        nonlocal ans
        best1 = best2 = 0
        for v, w in g[u]:
            if v == p:
                continue
            d = dfs(v, u) + w
            if d > best1:
                best2 = best1
                best1 = d
            elif d > best2:
                best2 = d
        ans = max(ans, best1 + best2)
        return best1
    dfs(0, -1)
    return ans

def solve(grid):
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = grid[0][0]
    for i in range(m):
        for j in range(n):
            if i:
                dp[i][j] = max(dp[i][j], dp[i - 1][j] + grid[i][j])
            if j:
                dp[i][j] = max(dp[i][j], dp[i][j - 1] + grid[i][j])
    return dp[-1][-1]

from collections import defaultdict

def solve(equations, values, queries):
    g = defaultdict(list)
    for (a, b), v in zip(equations, values):
        g[a].append((b, v))
        g[b].append((a, 1 / v))
    def dfs(a, b, seen):
        if a not in g:
            return -1.0
        if a == b:
            return 1.0
        seen.add(a)
        for nxt, w in g[a]:
            if nxt not in seen:
                r = dfs(nxt, b, seen)
                if r != -1:
                    return w * r
        return -1.0
    return [dfs(a, b, set()) for a, b in queries]

def solve(nums):
    take = skip = 0
    for x in nums:
        take, skip = skip + x, max(skip, take)
    return max(take, skip)

def solve(n, edges, src, dst):
    g = [[] for _ in range(n)]
    for u, v in edges:
        g[u].append(v)
    def dfs(u, seen):
        if u == dst:
            return 1
        ans = 0
        seen.add(u)
        for v in g[u]:
            if v not in seen:
                ans += dfs(v, seen)
        seen.remove(u)
        return ans
    return dfs(src, set())

def solve(n):
    MOD = 10**9 + 7
    if n <= 2:
        return n
    dp = [0] * (n + 1)
    dp[1], dp[2], dp[3] = 1, 2, 5
    for i in range(4, n + 1):
        dp[i] = (2 * dp[i - 1] + dp[i - 3]) % MOD
    return dp[n]

def solve(intervals):
    intervals.sort(key=lambda x: x[1])
    end = float('-inf')
    ans = 0
    for s, e in intervals:
        if s >= end:
            end = e
        else:
            ans += 1
    return ans

def solve(s):
    rev = s[::-1]
    t = s + '#' + rev
    lps = [0] * len(t)
    for i in range(1, len(t)):
        j = lps[i - 1]
        while j and t[i] != t[j]:
            j = lps[j - 1]
        if t[i] == t[j]:
            j += 1
        lps[i] = j
    return rev[:len(s) - lps[-1]] + s

def solve(nums):
    nums.sort()
    reach = 1
    for x in nums:
        if x > reach:
            break
        reach += x
    return reach
